import { useEffect, useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import type { AppHandle } from "@app/kit/primitives";

const HERO = "https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=2000&q=75";
const serif = { fontFamily: "'Iowan Old Style','Palatino Linotype',Palatino,Georgia,serif" } as const;

const GMark = () => (
  <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
    <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z" />
    <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z" />
    <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z" />
    <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z" />
  </svg>
);

function Counter({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(0);
  useEffect(() => {
    if (reduce) {
      setV(value);
      return;
    }
    let raf = 0;
    const t0 = performance.now();
    const tick = (t: number) => {
      const p = Math.min(1, (t - t0) / 1400);
      setV(Math.round(value * (1 - Math.pow(1 - p, 3))));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [value, reduce]);
  return <>{v}</>;
}

export default function TableforLogin({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const up = app?.auth.mode === "signup";
  const providers = app?.auth.providers ?? [];
  const canSignUp = app?.auth.canSignUp ?? true;

  const [slots, setSlots] = useState<Record<string, unknown>[]>([]);
  const [loads, setLoads] = useState<Record<string, unknown>[]>([]);
  useEffect(() => {
    if (!app) return;
    app.query("slot", { limit: 50 }).then((r) => setSlots(r.rows)).catch(() => undefined);
    app.query("slot_load", { limit: 200 }).then((r) => setLoads(r.rows)).catch(() => undefined);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const seatsLeft = (() => {
    const d = new Date();
    const iso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    return slots
      .filter((x) => String(x.service) === "dinner")
      .reduce((a, x) => {
        const used = loads
          .filter((l) => String(l.slot_id) === String(x.id) && String(l.date).slice(0, 10) === iso)
          .reduce((b, l) => b + (Number(l.seats) || 0), 0);
        return a + Math.max(0, (Number(x.capacity) || 0) - used);
      }, 0);
  })();

  const submit = async () => {
    if (!app || busy) return;
    setBusy(true);
    setErr("");
    try {
      if (!up) await app.auth.signIn(email.trim(), password);
      else await app.auth.signUp({ name: name.trim() || email.split("@")[0], email: email.trim(), password });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Something went wrong. Please try again.");
    } finally {
      setBusy(false);
    }
  };

  const provider = async (p: string) => {
    setErr("");
    try {
      await app?.auth.startProvider(p);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't start that sign-in. Please try again.");
    }
  };

  const flip = () => {
    app?.auth.setMode(up ? "login" : "signup");
    setErr("");
  };

  const input =
    "w-full rounded-xl border border-white/20 bg-white/10 px-4 py-3 text-[15px] text-white placeholder:text-white/40 outline-none transition focus:border-primary focus:bg-white/15 focus:ring-4 focus:ring-primary/25";
  const label = "mb-1.5 block text-[11px] font-semibold uppercase tracking-[0.14em] text-white/70";

  return (
    <div className="relative min-h-screen w-full overflow-hidden bg-[#1d110b] text-white">
      <motion.img
        src={HERO}
        alt=""
        className="absolute inset-0 h-full w-full object-cover"
        initial={reduce ? false : { scale: 1.15 }}
        animate={{ scale: 1 }}
        transition={{ duration: 3, ease: "easeOut" }}
      />
      <div className="absolute inset-0 bg-[#1d110b]/55" />
      <div className="absolute inset-0 bg-gradient-to-t from-[#1d110b] via-[#1d110b]/50 to-[#1d110b]/20" />
      <div className="absolute inset-0 bg-gradient-to-r from-[#1d110b]/80 via-transparent to-transparent" />
      {!reduce && (
        <motion.div
          aria-hidden="true"
          className="absolute right-[18%] top-[22%] h-72 w-72 rounded-full bg-primary/20 blur-3xl"
          animate={{ opacity: [0.35, 0.7, 0.45, 0.8, 0.35], scale: [1, 1.08, 1, 1.12, 1] }}
          transition={{ duration: 6, repeat: Infinity, ease: "easeInOut" }}
        />
      )}

      <motion.div
        className="absolute left-6 top-6 flex items-center gap-2.5 lg:left-14 lg:top-12"
        initial={reduce ? false : { opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.2 }}
      >
        <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-primary text-xl text-white shadow-lg shadow-primary/40" style={serif}>
          t
        </div>
        <span className="text-2xl tracking-tight" style={serif}>
          Tablefor
        </span>
      </motion.div>
      <motion.p
        className="absolute right-14 top-14 hidden max-w-xs text-right text-sm italic text-white/70 lg:block"
        style={serif}
        initial={reduce ? false : { opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1 }}
      >
        “Charred, smoked and meant to be shared.”
        <span className="mt-1 block text-xs not-italic uppercase tracking-[0.2em] text-white/50">Fig &amp; Ember · Old Market</span>
      </motion.p>

      <div className="absolute inset-x-0 bottom-0 flex max-h-screen items-end overflow-y-auto lg:bottom-12 lg:left-14 lg:right-auto lg:block lg:max-h-none lg:overflow-visible">
        <motion.div
          className="w-full rounded-t-[2rem] border border-white/15 bg-[#241610]/60 p-6 pb-8 shadow-2xl backdrop-blur-2xl lg:w-[26rem] lg:rounded-[2rem] lg:p-8"
          initial={reduce ? false : { y: 80, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ type: "spring", stiffness: 110, damping: 20, delay: 0.3 }}
        >
          <div className="flex items-center gap-2 text-[11px] font-semibold uppercase tracking-[0.18em] text-white/80">
            <span className="relative flex h-2 w-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-primary opacity-70" />
              <span className="relative inline-flex h-2 w-2 rounded-full bg-primary" />
            </span>
            {seatsLeft > 0 ? (
              <span>
                <span className="text-sm text-white tabular-nums">
                  <Counter value={seatsLeft} />
                </span>{" "}
                tables left tonight
              </span>
            ) : (
              <span>Tonight's tables are filling</span>
            )}
          </div>

          <h1 className="mt-3 text-3xl leading-[1.05] lg:text-4xl" style={serif}>
            {up ? "Pull up a chair." : "Your table is waiting."}
          </h1>
          <p className="mt-2 text-sm text-white/70">
            {up ? "Create an account to book tables and keep your QR passes." : "Sign in to book, see your passes, or run the floor."}
          </p>

          <div className="mt-5 space-y-3.5">
            <AnimatePresence initial={false}>
              {up && (
                <motion.div key="name" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                  <label htmlFor="tf-name" className={label}>
                    Name
                  </label>
                  <input id="tf-name" className={input} value={name} onChange={(e) => setName(e.target.value)} placeholder="Maya Lindqvist" />
                </motion.div>
              )}
            </AnimatePresence>
            <div>
              <label htmlFor="tf-email" className={label}>
                Email
              </label>
              <input id="tf-email" aria-label="Email" type="email" autoComplete="email" className={input} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" />
            </div>
            <div>
              <label htmlFor="tf-pass" className={label}>
                Password
              </label>
              <input
                id="tf-pass"
                aria-label="Password"
                type="password"
                autoComplete={up ? "new-password" : "current-password"}
                className={input}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") void submit();
                }}
                placeholder="••••••••"
              />
            </div>
          </div>

          <AnimatePresence>
            {err && (
              <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mt-3 rounded-xl bg-red-500/20 px-3 py-2 text-sm text-red-100">
                {err}
              </motion.p>
            )}
          </AnimatePresence>

          <motion.button
            whileTap={{ scale: 0.97 }}
            whileHover={{ y: -1 }}
            onClick={() => void submit()}
            disabled={busy}
            className="mt-5 w-full rounded-xl bg-primary px-5 py-3.5 text-[15px] font-semibold text-white shadow-lg shadow-primary/40 disabled:opacity-60"
          >
            {busy ? "One moment…" : up ? "Create account" : "Sign in"}
          </motion.button>

          {providers.length > 0 && (
            <>
              <div className="my-4 flex items-center gap-3 text-[11px] uppercase tracking-[0.2em] text-white/50">
                <span className="h-px flex-1 bg-white/15" />
                or
                <span className="h-px flex-1 bg-white/15" />
              </div>
              <div className="space-y-2.5">
                {providers.map((p) => (
                  <motion.button
                    key={p.name}
                    whileTap={{ scale: 0.97 }}
                    onClick={() => void provider(p.name)}
                    className="flex w-full items-center justify-center gap-3 rounded-xl bg-white px-5 py-3 text-[15px] font-semibold text-[#2A1A12] shadow-md"
                  >
                    {p.name === "google" && <GMark />}
                    Continue with {p.label}
                  </motion.button>
                ))}
              </div>
            </>
          )}

          {canSignUp && (
            <button onClick={flip} className="mt-4 w-full text-center text-sm text-white/70 underline-offset-4 hover:text-white hover:underline">
              {up ? "Already have an account? Sign in" : "New here? Create an account"}
            </button>
          )}
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react";
import { QRCodeSVG } from "qrcode.react";
import { Sparkles, CalendarDays, Clock, Flame, LogOut, Plus, QrCode, Users, Utensils, X, Check, MapPin } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Tab = "home" | "book" | "mine";

const serif = { fontFamily: "'Iowan Old Style','Palatino Linotype',Palatino,Georgia,serif" } as const;
const HERO = "https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1800&q=75";
const ROOM = "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=70";
const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const CATS = ["starter", "main", "dessert", "drink"] as const;
const CAT_LABEL: Record<string, string> = { starter: "Starters", main: "Mains", dessert: "Desserts", drink: "Drinks" };

const s = (v: unknown) => String(v ?? "");
const n = (v: unknown) => Number(v) || 0;
const ymd = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
const parse = (iso: string) => {
  const [y, m, d] = iso.slice(0, 10).split("-").map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
};
const nice = (iso: string) => {
  const d = parse(iso);
  return `${DAYS[d.getDay()].slice(0, 3)} ${d.getDate()} ${MONTHS[d.getMonth()]}`;
};
const makeCode = () => {
  const al = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let c = "FE-";
  for (let i = 0; i < 4; i++) c += al[Math.floor(Math.random() * al.length)];
  return c;
};

function Counter({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(0);
  useEffect(() => {
    if (reduce) {
      setV(value);
      return;
    }
    let raf = 0;
    const from = v;
    const t0 = performance.now();
    const tick = (t: number) => {
      const p = Math.min(1, (t - t0) / 700);
      setV(Math.round(from + (value - from) * (1 - Math.pow(1 - p, 3))));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, reduce]);
  return <>{v}</>;
}

function AskMenu({ app, dishes }: { app?: AppHandle; dishes: R[] }) {
  const [q, setQ] = useState("");
  const [busy, setBusy] = useState(false);
  const [picks, setPicks] = useState<{ d: R; why: string }[]>([]);
  const [msg, setMsg] = useState("");
  const ask = async () => {
    if (!app || !q.trim() || busy || !dishes.length) return;
    setBusy(true);
    setMsg("");
    setPicks([]);
    try {
      const menu = dishes.map((d) => `${s(d.name)} | ${s(d.tags)} | ${s(d.description)}`).join("\n");
      const out = await app.ai.ask(`Menu (name | tags | description):\n${menu}\n\nGuest: ${q.trim().slice(0, 200)}\nPick 2-3 dishes from the menu only. JSON only: [{\"name\":\"exact name\",\"why\":\"one short sentence\"}]`, { system: "You are the maitre d' of Fig & Ember. Recommend only listed dishes, respect dietary needs strictly, reply with JSON only.", maxTokens: 400 });
      const m = out.match(/\[[\s\S]*\]/);
      const arr = JSON.parse(m ? m[0] : "[]") as { name?: string; why?: string }[];
      const found: { d: R; why: string }[] = [];
      for (const a of arr) {
        const d = dishes.find((x) => s(x.name).toLowerCase() === s(a.name).toLowerCase());
        if (d && !found.some((f) => f.d === d)) found.push({ d, why: s(a.why) });
      }
      if (!found.length) setMsg("Nothing matches that — try describing it another way.");
      setPicks(found.slice(0, 3));
    } catch {
      setMsg("AI is resting right now, try again soon.");
    } finally {
      setBusy(false);
    }
  };
  return (
    <div className="mt-6 rounded-3xl border border-[#EADFC9] bg-white p-5 lg:p-6">
      <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.18em] text-primary"><Sparkles size={14} /> Ask the menu</div>
      <p className="mt-1 text-sm text-[#7a6650]">Tell us a craving or a dietary need.</p>
      <div className="mt-3 flex flex-col gap-2 sm:flex-row">
        <input aria-label="Ask the menu" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void ask(); }} placeholder="e.g. vegetarian, not too spicy" className="flex-1 rounded-2xl border border-[#E8DCC6] bg-[#FBF5EA] px-4 py-3 text-[15px] outline-none focus:border-primary" />
        <button disabled={busy || !q.trim()} onClick={() => void ask()} className="rounded-2xl bg-primary px-6 py-3 text-[15px] font-semibold text-white disabled:opacity-50">{busy ? "Thinking…" : "Suggest dishes"}</button>
      </div>
      {msg && !busy && <p className="mt-3 rounded-2xl bg-[#FBF5EA] px-4 py-3 text-sm text-[#7a6650]">{msg}</p>}
      <div className="mt-3 space-y-2">
        {picks.map((p, i) => (
          <motion.div key={s(p.d.id)} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.1 }} className="rounded-2xl bg-[#FBF5EA] p-3">
            <p className="flex justify-between gap-2 text-lg leading-tight" style={serif}><span>{s(p.d.name)}</span><span className="text-sm font-semibold text-primary">${n(p.d.price)}</span></p>
            <p className="text-sm text-[#7a6650]">{p.why}</p>
          </motion.div>
        ))}
      </div>
    </div>
  );
}

export default function GuestApp({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [tab, setTab] = useState<Tab>("home");
  const [today, setToday] = useState("");
  const [nowMin, setNowMin] = useState(-1);
  const [date, setDate] = useState("");
  const [party, setParty] = useState(2);
  const [slotId, setSlotId] = useState("");
  const [note, setNote] = useState("");
  const [cat, setCat] = useState<string>("starter");
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState<{ kind: "ok" | "err"; text: string } | null>(null);
  const [confirmed, setConfirmed] = useState<R | null>(null);
  const [openQr, setOpenQr] = useState("");

  useEffect(() => {
    const d = new Date();
    setToday(ymd(d));
    setDate(ymd(d));
    setNowMin(d.getHours() * 60 + d.getMinutes());
  }, []);
  useEffect(() => (app ? app.live("slot_load") : undefined), [app]);
  useEffect(() => (app ? app.live("booking") : undefined), [app]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3600);
    return () => clearTimeout(t);
  }, [toast]);

  const dishes = app?.rows("dish") ?? [];
  const slotsRaw = app?.rows("slot");
  const slots = useMemo(() => [...(slotsRaw ?? [])].sort((a, b) => n(a.sort) - n(b.sort)), [slotsRaw]);
  const loads = app?.rows("slot_load") ?? [];
  const hoursRaw = app?.rows("opening_hour");
  const hours = useMemo(() => [...(hoursRaw ?? [])].sort((a, b) => n(a.sort) - n(b.sort)), [hoursRaw]);
  const bookings = app?.rows("booking") ?? [];
  const loadingSlots = app ? app.loading("slot") : false;

  const dayHours = (iso: string) => hours.find((h) => s(h.day) === DAYS[parse(iso).getDay()]);
  const isClosed = (iso: string) => {
    const h = dayHours(iso);
    return h ? s(h.opens) === "Closed" : parse(iso).getDay() === 1;
  };
  const days = useMemo(() => {
    if (!today) return [] as string[];
    const base = parse(today);
    return Array.from({ length: 14 }, (_, i) => {
      const d = new Date(base);
      d.setDate(d.getDate() + i);
      return ymd(d);
    });
  }, [today]);

  const taken = (sid: string, iso: string) =>
    loads.filter((l) => s(l.slot_id) === sid && s(l.date).slice(0, 10) === iso).reduce((a, l) => a + n(l.seats), 0);
  const dayHr = dayHours(date);
  const lunchOpen = dayHr ? n(s(dayHr.opens).slice(0, 2)) <= 13 : true;
  const visibleSlots = slots.filter((sl) => (s(sl.service) === "lunch" ? lunchOpen : true));
  const slotPast = (sl: R) => date === today && nowMin >= 0 && n(s(sl.time).slice(0, 2)) * 60 + n(s(sl.time).slice(3, 5)) < nowMin;
  const selected = slots.find((x) => s(x.id) === slotId);
  const selLeft = selected ? n(selected.capacity) - taken(s(selected.id), date) : 0;
  const tonightLeft = today
    ? slots.filter((sl) => s(sl.service) === "dinner" && !slotPast(sl)).reduce((a, sl) => a + Math.max(0, n(sl.capacity) - taken(s(sl.id), today)), 0)
    : 0;

  useEffect(() => {
    if (selected && (selLeft < party || slotPast(selected))) setSlotId("");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [party, date, loads.length, selLeft]);

  const book = async () => {
    if (!app || !selected || busy) return;
    setBusy(true);
    try {
      const code = makeCode();
      const row = await app.create("booking", {
        guest_id: app.me("guest"),
        guest_name: app.user.name || "Guest",
        slot_id: s(selected.id),
        date,
        time: s(selected.time),
        starts_at: `${date}T${s(selected.time)}:00Z`,
        party_size: party,
        status: "booked",
        code,
        source: "online",
        note: note.trim() || undefined,
      });
      setConfirmed({ ...row, code, date, time: s(selected.time), party_size: party });
      setNote("");
      setSlotId("");
    } catch (e) {
      setToast({ kind: "err", text: e instanceof Error ? e.message : "We couldn't book that table." });
    } finally {
      setBusy(false);
    }
  };

  const cancel = async (b: R) => {
    if (!app) return;
    try {
      try {
        await app.update("booking", s(b.id), { status: "cancelled" });
      } catch {
        await app.transition("booking", s(b.id), "status", "cancelled");
      }
      setToast({ kind: "ok", text: "Booking cancelled. We hope to see you soon." });
      setOpenQr("");
    } catch (e) {
      setToast({ kind: "err", text: e instanceof Error ? e.message : "Couldn't cancel." });
    }
  };

  const mine = [...bookings].sort((a, b) => (s(a.starts_at) < s(b.starts_at) ? 1 : -1));
  const upcoming = mine.filter((b) => ["booked", "seated"].includes(s(b.status)) && s(b.date).slice(0, 10) >= (today || "0")).reverse();
  const past = mine.filter((b) => !upcoming.includes(b));

  const spring = reduce ? { duration: 0 } : { type: "spring" as const, stiffness: 320, damping: 26 };
  const tabs: { id: Tab; label: string; icon: typeof Flame }[] = [
    { id: "home", label: "Restaurant", icon: Utensils },
    { id: "book", label: "Book", icon: CalendarDays },
